using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Filters;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

namespace FiltersDemo;

// -- Authorization Filter --
public class RoleAuthorizeFilter : IAsyncAuthorizationFilter
{
    private readonly string _requiredRole;
    public RoleAuthorizeFilter(string requiredRole) => _requiredRole = requiredRole;

    public Task OnAuthorizationAsync(AuthorizationFilterContext context)
    {
        // 未认证 → 401
        if (context.HttpContext.User.Identity?.IsAuthenticated != true)
        {
            context.Result = new UnauthorizedResult();
            return Task.CompletedTask;
        }
        // 无权限 → 403
        if (!context.HttpContext.User.IsInRole(_requiredRole))
        {
            context.Result = new ForbidResult();
            return Task.CompletedTask;
        }
        return Task.CompletedTask;
    }
}

// -- Resource Filter: 简单内存缓存 --
public class MemoryCacheResourceFilter : IAsyncResourceFilter
{
    private static readonly ConcurrentDictionary<string, (object Value, DateTime Expiry)> Cache = new();
    private readonly int _seconds;
    public MemoryCacheResourceFilter(int seconds) => _seconds = seconds;

    public async Task OnResourceExecutionAsync(ResourceExecutingContext ctx, ResourceExecutionDelegate next)
    {
        var key = $"{ctx.HttpContext.Request.Path}{ctx.HttpContext.Request.QueryString}";
        if (Cache.TryGetValue(key, out var hit) && hit.Expiry > DateTime.UtcNow)
        {
            // 短路：直接返回缓存结果，跳过模型绑定和 Action
            ctx.Result = (IActionResult)hit.Value;
            return;
        }

        var resultCtx = await next(); // 继续执行后续管道

        if (resultCtx.Result is ObjectResult obj && resultCtx.Exception == null)
            Cache[key] = (obj, DateTime.UtcNow.AddSeconds(_seconds));
    }
}

// -- Action Filter: 计时 + 日志 --
public class TimingActionFilter : IAsyncActionFilter
{
    private readonly ILogger<TimingActionFilter> _logger;
    public TimingActionFilter(ILogger<TimingActionFilter> logger) => _logger = logger;

    public async Task OnActionExecutionAsync(ActionExecutingContext ctx, ActionExecutionDelegate next)
    {
        var sw = Stopwatch.StartNew();
        _logger.LogInformation("Action {Name} 开始", ctx.ActionDescriptor.DisplayName);

        var resultCtx = await next();

        sw.Stop();
        if (resultCtx.Exception != null && !resultCtx.ExceptionHandled)
            _logger.LogError(resultCtx.Exception, "Action {Name} 失败 ({Ms}ms)", ctx.ActionDescriptor.DisplayName, sw.ElapsedMilliseconds);
        else
            _logger.LogInformation("Action {Name} 完成 ({Ms}ms)", ctx.ActionDescriptor.DisplayName, sw.ElapsedMilliseconds);
    }
}

// -- Exception Filter: 全局异常处理 --
public class JsonExceptionFilter : IAsyncExceptionFilter
{
    private readonly ILogger<JsonExceptionFilter> _logger;
    public JsonExceptionFilter(ILogger<JsonExceptionFilter> logger) => _logger = logger;

    public Task OnExceptionAsync(ExceptionContext context)
    {
        _logger.LogError(context.Exception, "未处理异常");

        var code = context.Exception switch
        {
            ArgumentException => 400,
            UnauthorizedAccessException => 401,
            KeyNotFoundException => 404,
            _ => 500
        };

        context.Result = new ObjectResult(new
        {
            Code = code,
            Message = code == 500 ? "服务器内部错误" : context.Exception.Message,
            TraceId = Activity.Current?.Id ?? context.HttpContext.TraceIdentifier
        }) { StatusCode = code };

        context.ExceptionHandled = true;
        return Task.CompletedTask;
    }
}

// -- Result Filter: 统一响应包装 --
public class WrapResponseFilter : IAsyncResultFilter
{
    public async Task OnResultExecutionAsync(ResultExecutingContext ctx, ResultExecutionDelegate next)
    {
        if (ctx.Result is ObjectResult obj)
        {
            obj.Value = new { Code = obj.StatusCode ?? 200, Data = obj.Value, Timestamp = DateTime.UtcNow };
        }
        await next();
    }
}

// -- 控制器使用示例 --
[ApiController]
[Route("api/[controller]")]
public class ProductsController : ControllerBase
{
    [HttpGet]
    public IActionResult GetAll() => Ok(new[] { "A", "B" });

    [HttpGet("{id}")]
    public IActionResult GetById(int id)
    {
        if (id <= 0) throw new ArgumentException("ID 必须大于 0");
        if (id > 100) throw new KeyNotFoundException("产品不存在");
        return Ok($"Product {id}");
    }
}

// -- 注册 --
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<TimingActionFilter>();
builder.Services.AddScoped<JsonExceptionFilter>();
builder.Services.AddControllers(options =>
{
    options.Filters.AddService<JsonExceptionFilter>();           // 全局：异常处理
    options.Filters.AddService<WrapResponseFilter>();           // 全局：响应包装
    options.Filters.Add(new MemoryCacheResourceFilter(30));     // 全局：30s 缓存
});
var app = builder.Build();
app.MapControllers();
app.Run();
